#pragma once
/**
 * Partie en cours : jeu (voxel::Game), rendu du monde, son, commandes du
 * joueur, HUD et journal des messages. Les panneaux (inventaire,
 * fabrication, discussion, terminal…) sont des écrans du Shell qui
 * s'appuient sur cette session.
 */
#include <deque>
#include <memory>

#include <audio/engine.hpp>
#include <render3d/camera.hpp>
#include <ui/widget.hpp>
#include <voxel/game.hpp>

#include "catalog.hpp"
#include "worker.hpp"
#include "world_renderer.hpp"

namespace voxelia {

class Shell;

/// Ligne du journal (discussion, système, événements, commandes).
struct LogLine {
	String text;
	String channel; ///< « chat », « system », « event », « command », « result », « error »
	String author;  ///< joueur (discussion)
	double time = 0.0; ///< heure système (s) de réception
	float shown = 8.f; ///< secondes d'affichage restantes sur le HUD
};

/// Statistiques de la partie (écran d'informations du monde).
struct SessionStats {
	int blocksBroken = 0, blocksPlaced = 0, creaturesKilled = 0, deaths = 0, itemsCrafted = 0;
	double distance = 0.0;
	double sessionTime = 0.0;
};

class Session {
public:
	Session(Shell &shell, String folder);
	~Session();

	/// Étapes de chargement (une par image) : faux tant que ce n'est pas prêt.
	bool Prepare(float &progress, String &status);
	[[nodiscard]] bool Ready() const noexcept { return m_ready; }
	[[nodiscard]] const String &Error() const noexcept { return m_error; }

	void HandleEvent(sdl3::Event &e, bool captureAllowed);
	/// Commandes, actions, caméra, scène du monde, sons, HUD. Avec le fil de
	/// mise à jour, la simulation n'y avance pas : elle est réservée pour
	/// BeginSimulation (sinon elle avance ici, avant le reste).
	void Update(float dt, bool paused, bool panelOpen);
	/// Fil principal : lance sur le fil « voxel-update » le pas de simulation
	/// réservé par Update (voxel::Game::Tick : l'ECS, le monde, les scripts).
	/// Rien ne doit toucher au jeu avant EndSimulation.
	void BeginSimulation();
	/// Fil principal : attend la fin du pas de simulation en cours.
	void EndSimulation();
	/// Durée du dernier pas de simulation (ms, moyenne glissante).
	[[nodiscard]] float TickMilliseconds() const noexcept { return m_tickMs; }
	void BuildHud(ui::Widget layer);
	void SetHudVisible(bool visible);
	/// Remet les réglages (distance d'affichage, ombres…) au moteur.
	void ApplySettings();
	void Save(bool notify);

	// ── Accès ───────────────────────────────────────────────────────────────
	[[nodiscard]] voxel::Game &Game() noexcept { return *m_game; }
	[[nodiscard]] WorldRenderer &Renderer() noexcept { return *m_world; }
	[[nodiscard]] ecs::Entity Player() const noexcept { return m_player; }
	[[nodiscard]] voxel::Inventory *Inventory();
	[[nodiscard]] const String &Folder() const noexcept { return m_folder; }
	[[nodiscard]] const render3d::Camera &Camera() const noexcept { return m_camera; }
	[[nodiscard]] audio::AudioEngine &Audio() noexcept { return *m_audio; }
	[[nodiscard]] const std::deque<LogLine> &Log() const noexcept { return m_logLines; }
	[[nodiscard]] const SessionStats &Stats() const noexcept { return m_stats; }
	[[nodiscard]] std::vector<String> &History() noexcept { return m_history; }
	[[nodiscard]] float Fps() const noexcept { return m_fps; }
	[[nodiscard]] bool ThirdPerson() const noexcept { return m_thirdPerson; }
	/// Gravité inversée (le joueur marche au plafond) : vue et commandes retournées.
	[[nodiscard]] bool Inverted() const {
		if (!m_game)
			return false;
		auto body = m_game->Registry().GetComponent<voxel::PhysicsBody>(m_player);
		return body.IsSome() && body.Unwrap()->gravityDirection < 0.f;
	}

	// ── Actions ─────────────────────────────────────────────────────────────
	/// Message de discussion du joueur, ou commande (« / »).
	void Submit(const String &text);
	/// Exécute une commande ; rend le résultat (et l'ajoute au journal).
	Result<String, String> Command(const String &line);
	void Craft(const String &recipe, int times);
	void SelectSlot(int slot);
	[[nodiscard]] int SelectedSlot();
	void DropSelected(bool all = false);
	void SetCaptured(bool captured);
	[[nodiscard]] bool Captured() const noexcept { return m_captured; }
	/// Vignette du monde (capture de la vue 3D) : demandée à la sortie.
	void RequestThumbnail() { m_wantThumbnail = true; }
	[[nodiscard]] bool ThumbnailRequested() const noexcept { return m_wantThumbnail; }
	void ThumbnailTaken() { m_wantThumbnail = false; }
	/// Icône d'objet (case de l'atlas, en pixels de l'atlas) ; texture partagée.
	void DrawItem(sdl3::Renderer &ren, const voxel::ItemStack &stack, sdl3::FRect cell, bool count = true);
	[[nodiscard]] String ItemName(const String &id);

private:
	/// Un pas de simulation, chronométré (fil de mise à jour, ou sur place).
	void RunTick(float dt);
	void UpdateControls();
	void UpdateActions(float dt, const Option<voxel::BlockHit> &target);
	void UpdateSound();
	void UpdateMessages(float dt);
	void UpdateStats(float dt);
	void HandleUiRequests();
	void ResetBreaking();
	void PickBlock();
	render3d::Camera CameraFor();
	void DrawHud(sdl3::Renderer &ren, sdl3::FRect r);
	void DrawBars(sdl3::Renderer &ren, float x, float y, float width);
	void EnsureIcons(sdl3::Renderer &ren);
	void UpdateHudLabels();
	void AddLog(const String &text, const String &channel, const String &author = String());
	[[nodiscard]] float CategoryVolume(const String &sound) const;

	Shell &m_shell;
	String m_folder;
	std::unique_ptr<voxel::Game> m_game;
	std::unique_ptr<WorldRenderer> m_world;
	std::unique_ptr<audio::AudioEngine> m_audio;
	ecs::Entity m_player{};
	render3d::Camera m_camera;
	int m_stage = 0;
	size_t m_targetChunks = 1;
	bool m_ready = false;
	String m_error;

	// HUD
	ui::Widget m_hud, m_hudCanvas, m_infoPanel, m_targetPanel, m_targetName, m_targetDetail, m_hintPanel;
	ui::Widget m_chatPanel, m_debugPanel;
	std::array<ui::Widget, 3> m_infoLines{};
	std::array<ui::Widget, 8> m_chatLines{};
	std::array<ui::Widget, 8> m_chatRows{}; ///< fond de chaque ligne de discussion
	std::array<ui::Widget, 5> m_debugLines{};
	std::array<ui::Widget, 3> m_hintLines{};
	Option<sdl3::Texture> m_icons = NONE;
	bool m_hudVisible = true, m_debug = false, m_thirdPerson = false;

	// Commandes du joueur
	bool m_captured = false, m_leftDown = false, m_rightDown = false;
	bool m_sprintToggled = false, m_sneakToggled = false;
	float m_breakProgress = 0.f, m_hitTimer = 0.f, m_attackTimer = 0.f, m_useTimer = 0.f, m_breakRepeat = 0.f;
	voxel::BlockPos m_breaking{0, -100000, 0};
	float m_lastHealth = 1e9f, m_hurtFlash = 0.f, m_swing = 0.f, m_bob = 0.f;

	// Journal
	std::deque<LogLine> m_logLines;
	std::vector<String> m_history;
	uint64_t m_soundCursor = 0, m_messageCursor = 0, m_diedCursor = 0;
	SessionStats m_stats;
	math::FVector3 m_lastPosition{0.f, 0.f, 0.f};
	float m_fps = 0.f;
	long m_fpsFrames = 0;
	uint64_t m_fpsTicks = 0;
	bool m_wantThumbnail = false;
	audio::AudioEngine::VoiceId m_ambientVoice = audio::AudioEngine::NO_VOICE;

	// Fil de mise à jour (simulation).
	float m_pendingTick = -1.f; ///< pas réservé par Update (< 0 : aucun)
	float m_tickMs = 0.f;       ///< écrit par le fil de mise à jour, lu après EndSimulation
	bool m_ticked = false;      ///< un pas a été lancé depuis le dernier EndSimulation
	/// Dernier membre : détruit (joint) avant le jeu qu'il fait avancer.
	std::unique_ptr<Worker> m_updateThread;
};

} // namespace voxelia

#pragma once
/**
 * Préférences du joueur (indépendantes des mondes) : générales, commandes,
 * graphismes, son, jeu, accessibilité. Enregistrées dans
 * data/voxelia/settings.json ; les réglages propres à un monde (mode,
 * difficulté, règles) vivent dans sa sauvegarde (voxel::WorldMetadata).
 */
#include <array>
#include <map>
#include <vector>

#include <core/core.hpp>
#include <dataio/node.hpp>

namespace voxelia {

/// Entrée physique : touche (scancode SDL) ou bouton de souris (MOUSE_BASE + n).
inline constexpr int MOUSE_BASE = 1000;
inline constexpr int WHEEL_UP = 2000, WHEEL_DOWN = 2001;

struct KeyBinding {
	String action;   ///< « forward », « jump »…
	String label;    ///< « Avancer »
	String category; ///< « Déplacement », « Actions », « Interface »…
	std::array<int, 2> keys{0, 0}; ///< principale, secondaire (0 : aucune)
	std::array<int, 2> defaults{0, 0};
};

/// Nom lisible d'une entrée (« Z », « Clic gauche », « Molette ↑ »).
[[nodiscard]] String InputName(int code);

struct Settings {
	// ── Général ─────────────────────────────────────────────────────────────
	String language = "fr";
	String playerName = "Joueur";
	String skin;                  ///< id de texture ; vide : celui des mods
	bool confirmQuit = true, confirmDelete = true, confirmModChanges = true;
	int notifications = 2;        ///< 0 aucune, 1 importantes, 2 toutes
	float notificationSeconds = 4.f;
	int autosaveMinutes = 5;      ///< 0 : jamais
	bool showTips = true;
	bool pauseOnFocusLoss = true;

	// ── Commandes ───────────────────────────────────────────────────────────
	std::vector<KeyBinding> bindings;
	float mouseSensitivity = 1.f;
	bool invertY = false;
	float fov = 72.f;
	bool viewBobbing = true;
	bool allowDualBinding = false; ///< une même touche pour deux actions
	bool toggleSprint = false, toggleSneak = false;
	bool thirdPersonSmooth = true;

	// ── Graphismes ──────────────────────────────────────────────────────────
	int displayMode = 0;          ///< 0 fenêtre, 1 plein écran
	int width = 1280, height = 760;
	bool vsync = true;
	int fpsLimit = 0;             ///< 0 : illimité
	int viewDistance = 6;         ///< chunks
	int chunkUpdates = 8;         ///< reconstructions par image
	int shadows = 0;              ///< 0 désactivées, 1 proches, 2 étendues
	int dynamicLights = 8;        ///< lumières ponctuelles des blocs lumineux (0 : aucune)
	float brightness = 0.5f;      ///< 0..1
	bool ambientOcclusion = true;
	bool clouds = true;
	bool vignette = true;
	bool screenEffects = true;    ///< eau, dégâts
	int particles = 2;            ///< 0 aucune, 1 réduites, 2 toutes
	float vegetationDensity = 1.f;
	int entityDistance = 64;      ///< blocs

	// ── Son ─────────────────────────────────────────────────────────────────
	float masterVolume = 0.9f, musicVolume = 0.5f, effectsVolume = 1.f, ambienceVolume = 0.7f, uiVolume = 0.7f,
		  voiceVolume = 0.8f;
	bool spatialAudio = true;
	bool muteWhenUnfocused = false;

	// ── Jeu ─────────────────────────────────────────────────────────────────
	bool showCoordinates = true, showFps = false, showBiome = true, showClock = true;
	int crosshair = 0;            ///< 0 croix, 1 point, 2 cercle
	float hudOpacity = 0.85f;
	float hudScale = 1.f;
	bool autoJump = false;
	bool placeAssist = true;      ///< contour de pose du bloc
	bool showHints = true;        ///< indications de commandes contextuelles
	bool chatTimestamps = false;
	float chatOpacity = 0.6f;

	// ── Accessibilité ───────────────────────────────────────────────────────
	float uiScale = 1.f;
	float textScale = 1.f;
	bool highContrast = false;
	int colorBlind = 0;           ///< 0 aucun, 1 protanopie, 2 deutéranopie, 3 tritanopie
	bool subtitles = false;
	bool reduceMotion = false;
	bool reduceFlashes = false;
	float hudBackground = 0.35f;  ///< opacité du fond des textes du HUD
	int crosshairColor = 0;       ///< index de palette
	float crosshairSize = 1.f;
	bool smoothTextures = false;  ///< filtrage lissé au lieu du pixel net

	// ── Organisation des mods (préférences, pas la sauvegarde) ─────────────
	std::vector<String> modOrder;              ///< ordre de chargement souhaité
	std::map<std::string, String> modNames;    ///< nom d'affichage personnalisé (l'id interne ne change pas)
	std::map<std::string, String> modCategories; ///< catégorie personnalisée
	dataio::NodePtr modSettings;               ///< {mod: {réglage: valeur}} : valeurs globales
	[[nodiscard]] String ModName(const String &id, const String &fallback) const;

	/// Liste complète des actions et de leurs touches par défaut.
	void ResetBindings();
	[[nodiscard]] const KeyBinding *Binding(const String &action) const;
	/// Actions qui partagent une même entrée (conflits).
	[[nodiscard]] std::vector<std::pair<String, String>> Conflicts() const;
	/// Vrai si `code` déclenche `action`.
	[[nodiscard]] bool Matches(const String &action, int code) const;

	[[nodiscard]] dataio::NodePtr ToJson() const;
	void FromJson(const dataio::NodePtr &node);
	Result<bool, String> Save(const String &path) const;
	/// Lit le fichier (absent : valeurs par défaut).
	static Settings Load(const String &path);
};

} // namespace voxelia

#pragma once
/**
 * Coquille de l'application : écrans (pile de navigation), fenêtres
 * modales, notifications, monde de fond des menus, session de jeu.
 *
 * Couches (de bas en haut) : vue 3D (monde des menus ou de la partie), HUD
 * de la partie, écrans, notifications. Chaque écran est reconstruit quand
 * il revient au premier plan : il reflète toujours les données courantes
 * (mondes, mods, réglages).
 */
#include <deque>
#include <functional>
#include <memory>
#include <vector>

#include <audio/engine.hpp>
#include <render3d/canvas.hpp>
#include <sdl3/sdl3.hpp>
#include <ui/ui.hpp>

#include "app.hpp"
#include "catalog.hpp"
#include "settings.hpp"
#include "ui/kit.hpp"

namespace voxel {
class Game;
}

namespace voxelia {

class Shell;
class Session;
class WorldRenderer;

class Screen {
public:
	explicit Screen(Shell &shell);
	virtual ~Screen() = default;
	[[nodiscard]] virtual String Id() const = 0;
	/// Crée les widgets sous `root` (couche plein écran).
	virtual void Build(ui::Widget root) = 0;
	virtual void Update(float /*dt*/) {}
	/// Touche pressée (scancode) ; vrai si traitée.
	virtual bool OnKey(int /*scancode*/) { return false; }
	/// Échap / retour : vrai si l'écran l'a traité lui-même (sinon : Pop()).
	virtual bool OnBack() { return false; }
	/// Vrai : se superpose à l'écran précédent, qui reste affiché dessous.
	[[nodiscard]] virtual bool Overlay() const { return false; }
	/// Vrai : laisse la souris au jeu (aucun écran « bloquant »).
	[[nodiscard]] virtual bool PassThrough() const { return false; }

protected:
	Shell &shell;
	Kit &kit;
};

/// Demande de confirmation (suppression, sortie, changement important).
struct ConfirmSpec {
	String title, message;
	std::vector<String> details;     ///< liste à puces (conséquences)
	String confirmText = "Confirmer", cancelText = "Annuler";
	Tone tone = Tone::DANGER;
	ui::MaterialIcons icon = ui::MaterialIcons::WARNING;
	std::function<void()> onConfirm, onCancel;
	/// Case à cocher facultative (« Créer une sauvegarde de sécurité »).
	String checkboxText;
	bool checkboxValue = true;
	std::function<void(bool)> onCheckbox;
};

class Shell {
public:
	Shell(Options options, sdl3::Window &window, sdl3::Renderer &renderer, render3d::Canvas &canvas, ui::Ui &gui);
	~Shell();

	Result<bool, String> Initialize();
	[[nodiscard]] bool Running() const noexcept { return m_running; }
	void HandleEvent(sdl3::Event &e);
	void Update(float dt, long frame);
	/// Pas de simulation de la partie sur son fil (cf. Session::BeginSimulation).
	void BeginSimulation();
	/// Attend ce pas : à appeler avant tout accès au jeu (début d'image, sortie).
	void EndSimulation();
	/// Commande d'automatisation (--exec=N:!…) : « !screen nom », « !click texte »…
	void AppCommand(const String &line);
	/// Exécute une commande de jeu (console) si une partie est en cours.
	void GameCommand(const String &line);

	// ── Accès ───────────────────────────────────────────────────────────────
	[[nodiscard]] Settings &Prefs() noexcept { return m_settings; }
	[[nodiscard]] Kit &K() noexcept { return *m_kit; }
	[[nodiscard]] ui::Ui &Gui() noexcept { return m_gui; }
	[[nodiscard]] WorldCatalog &Worlds() noexcept { return m_worlds; }
	[[nodiscard]] ModCatalog &Mods() noexcept { return m_mods; }
	[[nodiscard]] Session *Game() noexcept { return m_session.get(); }
	[[nodiscard]] sdl3::Window &Window() noexcept { return m_window; }
	[[nodiscard]] sdl3::Renderer &Renderer() noexcept { return m_renderer; }
	[[nodiscard]] render3d::Canvas &Canvas() noexcept { return m_canvas; }
	[[nodiscard]] const Options &Opts() const noexcept { return m_options; }
	/// Jeu des menus (contenu de tous les mods installés : icônes, sons, skins).
	[[nodiscard]] voxel::Game *MenuGame() noexcept;
	[[nodiscard]] WorldRenderer *MenuRenderer() noexcept;
	[[nodiscard]] String Version() const { return String("0.6.0"); }
	[[nodiscard]] const std::vector<String> &RecentLog() const noexcept { return m_log; }
	void Log(const String &line);

	// ── Navigation ──────────────────────────────────────────────────────────
	void Push(std::unique_ptr<Screen> screen);
	void Pop();
	void Replace(std::unique_ptr<Screen> screen);
	/// Vide la pile (en jeu : retour à la partie ; sinon : menu principal).
	void ClearScreens();
	void Home();
	[[nodiscard]] Screen *Top() noexcept { return m_stack.empty() ? nullptr : m_stack.back().screen.get(); }
	[[nodiscard]] bool HasScreen(const String &id) const;
	/// Reconstruit l'écran du dessus (après un changement de données).
	void Rebuild();
	/// Reconstruit tous les écrans (thème ou échelle changés).
	void RebuildAll();

	// ── Dialogues et notifications ──────────────────────────────────────────
	void Confirm(ConfirmSpec spec);
	/// `important` : affichée même si l'utilisateur limite les notifications.
	void Notify(Tone tone, const String &title, const String &text = String(), bool important = false);
	void ShowError(const String &title, const String &message, const String &details);

	// ── Partie ──────────────────────────────────────────────────────────────
	void PlayWorld(const String &folder);
	void LeaveWorld(bool save);
	[[nodiscard]] bool InGame() const noexcept { return m_session != nullptr; }

	// ── Préférences ─────────────────────────────────────────────────────────
	void SaveSettings();
	/// Applique les préférences (thème, fenêtre, rendu, audio) et les enregistre.
	void ApplySettings(bool rebuild = true);
	/// Son d'interface (« ui_click », « ui_confirm »…).
	void UiSound(const char *id);
	void Quit() { m_running = false; }
	/// Capture d'écran (dossier data/voxelia/screenshots).
	void Screenshot(const String &path = String());

	/// Monde dont la vignette doit être prise à la prochaine image (quitter une partie).
	String pendingThumbnail;

private:
	struct Layer {
		std::unique_ptr<Screen> screen;
		ui::Widget root;
	};
	struct Toast {
		ui::Widget widget;
		float ttl = 0.f;
	};
	class Backdrop;

	void BuildLayers();
	void ShowTop();
	void DestroyLayer(Layer &layer);
	ui::Widget MakeLayerRoot(bool overlay);
	/// Couche du HUD (recréée à chaque partie), sous les écrans.
	void MakeHudLayer();
	void UpdateToasts(float dt);
	void UpdateViewport();
	void UpdateMenuAudio(float dt);
	/// Arrête la musique du menu (entrée dans une partie).
	void StopMenuMusic();
	/// Monde à ouvrir après l'écran de chargement (une image de délai).
	void StartLoading();

	Options m_options;
	sdl3::Window &m_window;
	sdl3::Renderer &m_renderer;
	render3d::Canvas &m_canvas;
	ui::Ui &m_gui;
	Settings m_settings;
	std::unique_ptr<Kit> m_kit;
	WorldCatalog m_worlds;
	ModCatalog m_mods;
	std::unique_ptr<Backdrop> m_backdrop;
	std::unique_ptr<Session> m_session;
	std::vector<Layer> m_stack;
	std::deque<Toast> m_toasts;
	ui::Widget m_viewport, m_hudLayer, m_screenLayer, m_toastLayer;
	std::vector<String> m_log;
	String m_loadingWorld;
	int m_loadingDelay = 0;
	bool m_running = true;
	bool m_rebuildAll = false;
	float m_autosaveTimer = 0.f;
	audio::AudioEngine::VoiceId m_menuMusic = audio::AudioEngine::NO_VOICE;
};

